/**
 * LUT (Luther Bible - German) to KJV Verse Numbering Mapping
 * 
 * Maps LUT verse numbers to KJV verse numbers for accurate cross-translation referencing.
 * 
 * Structure: book -> chapter -> { lutVerse: kjvVerse }
 * 
 * Note: This mapping is used when:
 * - Displaying cross-translation references
 * - Converting verse references for WordPress post lookups
 * - Showing equivalent verses between translations
 */

// JSON uses string keys, so we need to support both
export type VerseMapping = {
  [lutVerse: string]: string | number; // Maps LUT verse number (as string key) to KJV verse number
};

export type ChapterMapping = {
  [chapter: string]: VerseMapping; // Chapter numbers are strings in JSON
};

export type BookMapping = {
  [book: string]: ChapterMapping;
};

/**
 * LUT to KJV verse number mappings
 * 
 * Format: {
 *   "bookName": {
 *     chapterNumber: {
 *       lutVerseNumber: kjvVerseNumber
 *     }
 *   }
 * }
 * 
 * This mapping is auto-generated by scripts/generateLutToKjvMapping.ts
 * Run `npm run generate-lut-mapping` to regenerate.
 */
import lutToKjvMappingData from './lutToKjv.json';

// Type assertion needed because JSON uses string keys/values but we use numbers at runtime
export const lutToKjvMapping: BookMapping = lutToKjvMappingData as BookMapping;

/**
 * Get KJV verse number for a given LUT verse
 * 
 * @param book - Bible book name (normalized)
 * @param chapter - Chapter number
 * @param lutVerse - LUT verse number
 * @returns KJV verse number, or null if no mapping exists
 */
export const getKjvVerseFromLut = (
  book: string,
  chapter: number,
  lutVerse: number
): number | null => {
  const normalizedBook = book.toLowerCase().trim().replace(/\s+/g, '');
  const bookMapping = lutToKjvMapping[normalizedBook];
  
  if (!bookMapping) {
    return null; // No mapping for this book
  }
  
  // JSON uses string keys for chapters
  const chapterMapping = bookMapping[chapter.toString()];
  if (!chapterMapping) {
    return null; // No mapping for this chapter
  }
  
  // JSON keys are strings, so convert to string for lookup
  // Value may be string or number from JSON, so ensure it's a number
  const kjvVerse = chapterMapping[lutVerse.toString()];
  if (kjvVerse === undefined || kjvVerse === null) {
    return null;
  }
  
  // Convert to number if it's a string
  return typeof kjvVerse === 'string' ? parseInt(kjvVerse, 10) : kjvVerse;
};

/**
 * Check if a book/chapter has LUT to KJV mappings
 */
export const hasLutToKjvMapping = (book: string, chapter: number): boolean => {
  const normalizedBook = book.toLowerCase().trim().replace(/\s+/g, '');
  const bookMapping = lutToKjvMapping[normalizedBook];
  // JSON uses string keys for chapters
  return !!(bookMapping && bookMapping[chapter.toString()]);
};

